"""Scope computation for the review orchestrator.

Deterministic git/project context: git guard, PR scope + merge base,
guidance handling, standards gathering, and a project probe
(name/language/build system/test framework).
"""

import json
import re
import subprocess
from collections import Counter
from dataclasses import dataclass
from pathlib import Path


class ScopeError(Exception):
    """Unrecoverable scope problem — abort the review with this message."""


@dataclass
class ReviewScope:
    """Everything deterministic the pipeline knows about one review target."""

    project_root: str
    project_name: str
    default_branch: str  # e.g. "origin/main"
    language: str
    build_system: str
    test_framework: str
    pr_number: int | None = None
    # What the PR merges into (e.g. "origin/devel"), and where that came from
    # (see resolve_base_branch). Empty for full-repo reviews. Defaulted so a
    # scope.json written before these fields existed still loads on resume.
    base_branch: str = ""
    base_source: str = ""
    merge_base: str = ""  # empty for full-repo reviews
    pr_scope_text: str = ""  # "## PR Scope" block for agent prompts
    guidance: str = ""
    standards: str = ""  # external + local standards text
    scope_slug: str = ""  # e.g. "pr-42"; empty when unconstrained
    # Why the thing under review exists: PR/issue description, acceptance
    # criteria, or what the person running the review said it is for. Gathered
    # by the skill (which has the session's tools) and handed in as text —
    # nothing here fetches it. Empty is normal and is reported as such.
    intent: str = ""
    # Criticality profile (scripts.envelope.PROFILES). "" means the caller
    # never chose one, which is what lets the docs-only hint tell "forgot" from
    # a deliberate --profile code; everything that buckets reads it through
    # effective_profile.
    profile: str = ""
    # Every in-scope file is documentation or repo plumbing (is_docs_only).
    docs_only: bool = False

    @property
    def effective_profile(self) -> str:
        return self.profile or "code"


def _git(project_root: str, *args: str) -> str:
    proc = subprocess.run(
        ["git", *args],
        cwd=project_root,
        capture_output=True,
        text=True,
    )
    if proc.returncode != 0:
        raise subprocess.CalledProcessError(
            proc.returncode, proc.args, proc.stdout, proc.stderr
        )
    return proc.stdout.strip()


def check_git_context(project_root: str) -> str:
    """Return the default branch (e.g. origin/main) or raise ScopeError."""
    try:
        _git(project_root, "rev-parse", "--is-inside-work-tree")
    except (subprocess.CalledProcessError, OSError) as exc:
        raise ScopeError(
            "Not inside a git repository. Are you in the right directory?"
        ) from exc
    try:
        ref = _git(project_root, "symbolic-ref", "refs/remotes/origin/HEAD")
    except subprocess.CalledProcessError as exc:
        detail = (exc.stderr or "").strip().splitlines()
        raise ScopeError(
            "Cannot determine default branch. Are you in the right directory?"
            + (f" ({detail[0]})" if detail else "")
        ) from exc
    return ref.removeprefix("refs/remotes/")


def resolve_base_branch(
    project_root: str, pr_number: int, explicit: str, default_branch: str
) -> tuple[str, str]:
    """Return (base ref, source) for the PR: what it actually merges into.

    Precedence: --base, then `gh pr view`. Neither → ScopeError, never a
    guess: a PR into a feature branch diffed against main reports every
    commit that branch carries as the PR's own, and a whole review run
    against that diff is paid for before anyone notices. The error carries
    `base-hint:` lines naming candidates for the caller to offer.
    A base that is found but has no local ref is NOT replaced by the default
    branch — compute_pr_scope then warns naming the missing ref.
    """
    if explicit:
        name, source = explicit, "--base"
    else:
        name, source = _base_from_gh(project_root, pr_number), "gh pr view"
    if not name:
        hints = [
            f"base-hint: closer: {ref}: {commits} commit(s) ahead"
            # 2 + default fits Codex's 3-option question limit.
            for ref, commits in closer_branches(project_root, default_branch)[:2]
        ]
        hints.append(f"base-hint: default: {default_branch}")
        raise ScopeError(
            f"PR #{pr_number} target branch unknown: pass --base <branch> "
            "(gh pr view could not say).\n" + "\n".join(hints)
        )
    return (name if name.startswith("origin/") else f"origin/{name}"), source


def _base_from_gh(project_root: str, pr_number: int) -> str:
    """Base branch name via the gh CLI, or "" when gh is absent/offline."""
    try:
        proc = subprocess.run(
            ["gh", "pr", "view", str(pr_number), "--json", "baseRefName", "--jq", ".baseRefName"],
            cwd=project_root,
            capture_output=True,
            text=True,
            timeout=30,
        )
    except (OSError, subprocess.TimeoutExpired):
        return ""
    return proc.stdout.strip() if proc.returncode == 0 else ""


def closer_branches(project_root: str, base_branch: str) -> list[tuple[str, int]]:
    """Remote branches HEAD has fewer own commits over than base_branch.

    A PR cut from a feature branch shows up here: diffed against main it
    carries the feature branch's commits too, so the feature branch is
    "closer". Returns (ref, commits HEAD has beyond it), nearest first;
    empty when nothing is closer or git cannot say. Refs already containing
    HEAD (the PR's own branch) are skipped.
    """
    # ponytail: %(ahead-behind) needs git >= 2.41; older git yields no hint
    # rather than one rev-list per remote branch.
    try:
        out = _git(
            project_root,
            "for-each-ref",
            "--format=%(refname) %(ahead-behind:HEAD)",
            "refs/remotes/origin/",
        )
    except (subprocess.CalledProcessError, OSError):
        return []
    counts: dict[str, int] = {}
    for line in out.splitlines():
        parts = line.split()
        if len(parts) == 3 and parts[2].isdigit() and parts[0] != "refs/remotes/origin/HEAD":
            counts[parts[0].removeprefix("refs/remotes/")] = int(parts[2])
    if base_branch not in counts:
        return []
    limit = counts[base_branch]
    return sorted(
        ((ref, n) for ref, n in counts.items() if 0 < n < limit),
        key=lambda item: item[1],
    )


def compute_pr_scope(
    project_root: str, pr_number: int, base_branch: str
) -> tuple[str, str]:
    """Return (PR scope text block, merge base hash).

    Warnings are non-fatal: the block carries the warning and merge base
    stays empty (the diff-scope filter then no-ops).
    """
    header = f"## PR Scope: #{pr_number}\n"
    try:
        base = _git(project_root, "merge-base", "HEAD", base_branch)
    except subprocess.CalledProcessError:
        return (
            header
            + f"\nWARNING: Could not determine merge base against {base_branch}.",
            "",
        )
    try:
        diff_stat = _git(project_root, "diff", "--stat", f"{base}..HEAD")
    except subprocess.CalledProcessError:
        return (
            header + "\nWARNING: Could not compute diff stats against the merge base.",
            "",
        )
    if not diff_stat:
        return (
            header
            + "\nWARNING: No changed files detected between merge base and HEAD.",
            "",
        )
    text = f"""{header}
Merge base: {base[:12]} (against {base_branch})

### Diff Stats

{diff_stat}

### Scope Rules

- Report findings ONLY for the changed files listed above.
- You may read other files for context (understanding imports, call sites, interfaces),
  but do not report findings against unchanged files.
- When a changed file interacts with unchanged code in a problematic way, report the
  finding against the changed file with a note about the interaction.
- The output filename slug is: pr-{pr_number}"""
    return text, base


def gather_standards(project_root: str) -> str:
    """External standards plus local CLAUDE.md/AGENTS.md.

    External standards inject only for user-owned repos (gh login == origin
    owner) when ~/source/standards exists; every failure degrades to "".
    """
    parts: list[str] = []

    external = _external_standards(project_root)
    if external:
        parts.append(external)

    for name in ("CLAUDE.md", "AGENTS.md"):
        path = Path(project_root) / name
        if path.is_file():
            parts.append(
                f"### Project standards ({name})\n\n{path.read_text(encoding='utf-8')}"
            )

    return "\n\n".join(parts)


def _remote_owner(url: str) -> str:
    """Top-level owner segment of a git remote URL.

    Handles https://host/owner[/sub]/repo and git@host:owner[/sub]/repo —
    the owner is the first path segment, not the second-to-last (which
    breaks on nested/subgroup paths).
    """
    path = url.rstrip("/")
    if "://" in path:
        path = path.split("://", 1)[1]
        path = path.split("/", 1)[1] if "/" in path else ""
    elif ":" in path:
        path = path.split(":", 1)[1]
    return path.split("/", 1)[0] if path else ""


def _external_standards(project_root: str) -> str:
    standards_dir = Path.home() / "source" / "standards"
    claude_md = standards_dir / "CLAUDE.md"
    if not claude_md.is_file():
        return ""
    try:
        gh_user = subprocess.run(
            ["gh", "api", "user", "--jq", ".login"],
            capture_output=True,
            text=True,
            timeout=30,
        )
        if gh_user.returncode != 0:
            return ""
        url = _git(project_root, "remote", "get-url", "origin")
    except (subprocess.CalledProcessError, OSError, subprocess.TimeoutExpired):
        return ""
    owner = _remote_owner(url)
    if gh_user.stdout.strip() != owner:
        return ""
    text = claude_md.read_text(encoding="utf-8")
    return re.sub(r"\]\(([^)]+)\)", r"](~/source/standards/\1)", text)


_LANGUAGE_EXTENSIONS = {
    ".py": "Python",
    ".go": "Go",
    ".js": "JavaScript",
    ".ts": "TypeScript",
    ".rs": "Rust",
    ".java": "Java",
    ".rb": "Ruby",
    ".sh": "Shell",
    ".c": "C",
    ".cpp": "C++",
}


_DOC_EXTENSIONS = frozenset({
    ".md", ".markdown", ".rst", ".adoc", ".asciidoc", ".txt", ".pdf",
    ".png", ".jpg", ".jpeg", ".gif", ".svg", ".webp",
})
# Files every repo carries regardless of what it delivers. Dotfiles and
# dot-directories (.github/, .gitignore, lint configs) are matched separately.
_PLUMBING_NAMES = frozenset({"Makefile", "LICENSE"})


def is_docs_only(paths: list[str]) -> bool:
    """True when every path is documentation or repo plumbing, and at least
    one is documentation.

    Deterministic on the file list alone. Anything unrecognized counts as
    code, so an unfamiliar file suppresses the docs hint rather than
    triggering it.
    """
    saw_doc = False
    for path in paths:
        parts = Path(path).parts
        if any(part.startswith(".") for part in parts):
            continue
        if parts and parts[-1] in _PLUMBING_NAMES:
            continue
        if Path(path).suffix.lower() in _DOC_EXTENSIONS:
            saw_doc = True
            continue
        return False
    return saw_doc


def in_scope_files(project_root: str, merge_base: str) -> list[str]:
    """Files the review covers: the PR diff, or every tracked file."""
    try:
        if merge_base:
            out = _git(project_root, "diff", "--name-only", f"{merge_base}..HEAD")
        else:
            out = _git(project_root, "ls-files")
    except (subprocess.CalledProcessError, OSError):
        return []
    return out.splitlines()


def probe_project(project_root: str) -> tuple[str, str, str, str]:
    """Return (name, language, build_system, test_framework) deterministically."""
    root = Path(project_root)

    try:
        url = _git(project_root, "remote", "get-url", "origin")
        name = url.rstrip("/").rsplit("/", 1)[-1].removesuffix(".git")
    except (subprocess.CalledProcessError, OSError):
        name = root.resolve().name

    try:
        files = _git(project_root, "ls-files").splitlines()
    except (subprocess.CalledProcessError, OSError):
        files = [str(p.relative_to(root)) for p in root.rglob("*") if p.is_file()]
    counts = Counter(
        Path(f).suffix for f in files if Path(f).suffix in _LANGUAGE_EXTENSIONS
    )
    language = (
        _LANGUAGE_EXTENSIONS[counts.most_common(1)[0][0]] if counts else "unknown"
    )

    if (root / "Makefile").is_file():
        build_system = "make"
    elif (root / "package.json").is_file():
        build_system = "npm"
    elif (root / "pyproject.toml").is_file():
        build_system = "python/pyproject"
    else:
        build_system = "unknown"

    test_framework = "unknown"
    if (root / "pyproject.toml").is_file() or language == "Python":
        test_framework = "pytest"
    elif (root / "package.json").is_file():
        try:
            pkg = json.loads((root / "package.json").read_text(encoding="utf-8"))
            if "test" in pkg.get("scripts", {}):
                test_framework = "npm test"
        except (json.JSONDecodeError, OSError):
            pass
    elif language == "Go":
        test_framework = "go test"

    return name, language, build_system, test_framework


def compute_scope(
    project_root: str,
    pr_number: int | None,
    guidance: str,
    intent: str = "",
    profile: str = "",
    base: str = "",
) -> ReviewScope:
    """Build the full ReviewScope: git context, PR scope, standards, probe."""
    default_branch = check_git_context(project_root)
    name, language, build_system, test_framework = probe_project(project_root)

    scope = ReviewScope(
        project_root=project_root,
        project_name=name,
        default_branch=default_branch,
        language=language,
        build_system=build_system,
        test_framework=test_framework,
        pr_number=pr_number,
        guidance=guidance.strip(),
        standards=gather_standards(project_root),
        intent=intent.strip(),
        profile=profile,
    )
    if pr_number is not None:
        scope.base_branch, scope.base_source = resolve_base_branch(
            project_root, pr_number, base, default_branch
        )
        scope.pr_scope_text, scope.merge_base = compute_pr_scope(
            project_root, pr_number, scope.base_branch
        )
        scope.scope_slug = f"pr-{pr_number}"
    elif scope.guidance:
        # Slug from guidance: max 12 chars, lowercase, hyphens (SKILL.md rule).
        slug = re.sub(r"[^a-z0-9]+", "-", scope.guidance.lower()).strip("-")[:12]
        scope.scope_slug = slug.strip("-")
    scope.docs_only = is_docs_only(in_scope_files(project_root, scope.merge_base))
    return scope
